+struct File {
+    /// The handle to the preview2 descriptor that this file is referencing.
+    fd: wasi::filesystem::Descriptor,
+
+    /// The current-position pointer.
+    position: Arc<AtomicU64>,
+
+    /// In append mode, all writes append to the file.
+    append: bool,
+
