+// Find first non-empty buffer.
+fn first_non_empty_ciovec(ciovs: &types::CiovecArray<'_>) -> ErrnoResult<Option<Vec<u8>>> {
+    ciovs
+        .iter()
+        .map(|iov| {
+            let iov = iov
+                .or(Err(types::Errno::Inval))?
+                .read()
+                .or(Err(types::Errno::Inval))?;
+            if iov.buf_len == 0 {
+                return Ok(None);
+            }
+            iov.buf
+                .as_array(iov.buf_len)
+                .to_vec()
+                .or(Err(types::Errno::Inval))
+                .map(Some)
+        })
+        .find_map(Result::transpose)
+        .transpose()
+}
+
+// Find first non-empty buffer.
