+    iovs.iter()
+        .map(|iov| {
+            let iov = iov
+                .or(Err(types::Errno::Inval))?
+                .read()
+                .or(Err(types::Errno::Inval))?;
+            if iov.buf_len == 0 {
+                return Ok(None);
+            }
+            iov.buf
+                .as_array(iov.buf_len)
+                .as_slice_mut()
+                .map_err(|_| types::Errno::Inval)
+        })
+        .find_map(Result::transpose)
