+        let wasi::preopens::StdioPreopens {
+            stdin,
+            stdout,
+            stderr,
+        } = preopens
+            .get_stdio()
+            .await
+            .context("failed to call `get-stdio`")
+            .map_err(types::Error::trap)?;
