+    let mut grow_memory = shared_memory.clone();
+    let grow_thread = std::thread::spawn(move || {
+        for i in 0..NUM_GROW_OPS {
+            if grow_memory.grow(1).is_err() {
+                println!("stopping at grow operation #{}", i);
+                break;
+            }
+        }
+    });
