+
+        // Still holding the tree alive at this point.
+        assert_eq!(num_refs_dropped.load(SeqCst), 0);
+    }
+
+    // Not holding the tree alive anymore; should transitively drop everything
+    // we created.
+    store.gc();
+    assert_eq!(num_refs_dropped.load(SeqCst), expected);
+
+    Ok(())
+}
