+    ///
+    /// If the endianness is not explicitly specified, this will return `None`,
+    /// which means "native endianness".
+    pub const fn explicit_endianness(self) -> Option<Endianness> {
+        if self.read_bit(BIT_LITTLE_ENDIAN) {
