+
+impl Drop for OpaqueRootScope<'_> {
+    fn drop(&mut self) {
+        self.store.exit_gc_lifo_scope(self.scope);
+    }
+}
+
+impl Deref for OpaqueRootScope<'_> {
+    type Target = StoreOpaque;
+
+    fn deref(&self) -> &Self::Target {
+        self.store
+    }
+}
