+            let key_index = FuncKeyIndex::from_raw(key_index);
+            Some(key_index)
+        } else {
+            let sparse_start = self.inner.sparse_starts[ns_idx];
+            if self.inner.sparse_indices.len() > sparse_start.index() {
+                let (_, &key_index) = self.inner.sparse_indices.last().unwrap();
+                Some(key_index)
